"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[3729],{3729:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/06c065c1486d4bfa093cdc93ac7013cf.jpg\\"\\n  title=\\"88 Grilled Fish\\"\\n  cuisine=\\"Korean Food\\"\\n  address=\\"71 Jungangbudu-gil, Sokcho-si, Gangwon-do\\"\\n  rating=4\\n  tags=\\"restaurant\\"\\n/>\\n</center>\\n\\n## Ordered\\n```menu\\n{\\n\\"title\\": \\"88 Assorted Grilled Fish Set\\",\\n\\"rating\\": 4\\n}\\n---\\nThere is more quantity than expected and various types.\\n```\\n## Review\\nAs soon as you enter, they ask for the number of people and it\'s set up immediately with charcoal fire.  \\nThey grill the prepared fish right away.  \\nGrilled fish directly on charcoal fire is indeed the truth!  \\nThe squid muk-jeot served as a side dish is really delicious. They say they also sell it separately.  \\nSelf-service side dish refills are available, and I refilled the squid muk-jeot twice. Heh.\\n## Pictures\\n<pictures>\\n<img style=\\"max-width: 100%; height: auto;\\" src=\\"/assets/snippets/location/c2db399e859001c57b0700bc1de92493.jpg\\" alt=\\"88 Grilled Fish\\">\\n<img style=\\"max-width: 100%; height: auto;\\" src=\\"/assets/snippets/location/be24b60ba8d18e0e26f276d716e8a985.jpg\\" alt=\\"88 Grilled Fish\\">\\n<img style=\\"max-width: 100%; height: auto;\\" src=\\"/assets/snippets/location/60b4e5a3685ee0fb5fb09d2bd8e0e129.jpg\\" alt=\\"88 Grilled Fish\\">\\n<img style=\\"max-width: 100%; height: auto;\\" src=\\"/assets/snippets/location/e35ddf43fcdcb6240300266a64e3b83e.jpg\\" alt=\\"88 Grilled Fish\\">\\n</pictures>\\n"}')}}]);